def truncate_middle(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    keep = maxlen - 3
    left = (keep + 1) // 2
    right = keep - left
    return s[:left] + '...' + (s[len(s) - right:] if right > 0 else '')

