def is_valid_date_range(start, end):
    def parse(s):
        parts = s.split('-')
        if len(parts) != 3:
            return None
        y, m, d = parts
        if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit()):
            return None
        year, month, day = int(y), int(m), int(d)
        if not (1 <= year <= 9999 and 1 <= month <= 12):
            return None
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        dim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if not (1 <= day <= dim[month - 1]):
            return None
        return (year, month, day)
    s1 = parse(start)
    s2 = parse(end)
    if s1 is None or s2 is None:
        return False
    return s1 <= s2

def pad_to_multiple(s, multiple, ch):
    if multiple <= 0:
        return s
    remainder = len(s) % multiple
    if remainder == 0:
        return s
    return s + ch * (multiple - remainder)

