def tokenize_camel_case(s):
    if not s:
        return []
    words = []
    current = s[0]
    for c in s[1:]:
        if c.isupper():
            words.append(current)
            current = c
        else:
            current += c
    words.append(current)
    return words

def sort_by_abs_diff_from_median(nums):
    s = sorted(nums)
    n = len(s)
    med = float(s[n // 2]) if n % 2 == 1 else (s[n // 2 - 1] + s[n // 2]) / 2
    return sorted(nums, key=lambda x: (abs(x - med), x))

