def time_until_event(current_time, event_time):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    c, e = to_min(current_time), to_min(event_time)
    if e == c:
        return 0
    diff = e - c
    if diff < 0:
        diff += 1440
    return diff

def truncate_with_ellipsis(s, max_len):
