def compress_consecutive_duplicates(s):
    if not s:
        return ""
    out = [s[0]]
    for ch in s[1:]:
        if ch != out[-1]:
            out.append(ch)
    return ''.join(out)

def is_valid_hashtag(s):
    if len(s) < 2 or s[0] != '#':
        return False
    body = s[1:]
    if len(body) > 30:
        return False
    if not body[0].isalpha():
        return False
    return all(c.isalnum() or c == '_' for c in body)
